const byKey = new Map();
for (const s of UNIT_SPECS) byKey.set(key(s.brandId, s.model), s);

function key(brandId, model) {
  return String(brandId || '').toLowerCase() + '|' + code(model);
}

function code(model) {
  return String(model || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

/**
 * Specifications for a model, or null when the sheets do not carry it.
 *
 * A catalogue name may trail a description ("FDYA160AV19 — Slimline") and a
 * supplier code may be the "INDOOR / OUTDOOR" pair, so the indoor half is taken
 * and compared on letters and digits alone. Failing an exact match, the longest
 * transcribed code that is a prefix of the wanted one wins — that catches
 * regional suffixes like ".TH" and "/SA" without matching a different model in
 * the same family.
 */
export function findUnitSpec(brandId, model) {
  if (!model) return null;
  const indoor = String(model).split(/\s*\/\s*/)[0].split('—')[0].trim();
  const exact = byKey.get(key(brandId, indoor));
  if (exact) return exact;

  const wanted = code(indoor);
  if (wanted.length < 5) return null;
  const brand = String(brandId || '').toLowerCase();
  let best = null;
  for (const s of UNIT_SPECS) {
    if (s.brandId !== brand) continue;
    const c = code(s.model);
    if (c.length < 5) continue;
    if (wanted.startsWith(c) || c.startsWith(wanted)) {
      if (!best || c.length > code(best.model).length) best = s;
    }
  }
  return best;
}

/** Every transcribed model for a brand, largest first. */
export function specsForBrand(brandId) {
  return UNIT_SPECS.filter(s => s.brandId === String(brandId || '').toLowerCase())
    .sort((a, b) => b.kw - a.kw);
}
